import { createServer, IncomingMessage, ServerResponse } from 'node:http'
import { spawn } from 'node:child_process'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { existsSync } from 'node:fs'
import path from 'node:path'

const ROOT = process.env.MCAGENT_ROOT || '/var/www/xavi/mcagent'
const PORT = Number(process.env.MCAGENT_BOTOPS_PORT || 8791)
const TOKEN = process.env.MCAGENT_BOTOPS_TOKEN || ''
const GENERATED = path.join(ROOT, 'config', 'generated')
const PODMAN_ENV = path.join(ROOT, 'config', 'podman', 'mcagent.env')
const AUTH_CACHE = path.join(ROOT, 'config', 'auth-cache')

type Json = Record<string, unknown>

createServer(async (req, res) => {
  try {
    if (!authorized(req)) return send(res, 401, { ok: false, error: 'unauthorized' })
    const url = new URL(req.url || '/', 'http://127.0.0.1')
    if (req.method === 'GET' && url.pathname === '/health') return send(res, 200, { ok: true, service: 'mcagent-botops' })
    if (req.method === 'GET' && url.pathname === '/status') return send(res, 200, await status())
    if (req.method === 'POST' && url.pathname === '/config/accounts') return send(res, 200, await writeAccounts(await body(req)))
    if (req.method === 'POST' && url.pathname === '/podman/build') return send(res, 200, await run(['npm', 'run', 'podman:build']))
    if (req.method === 'POST' && url.pathname === '/podman/start') return send(res, 200, await startContainer(await body(req)))
    if (req.method === 'POST' && url.pathname === '/podman/stop') return send(res, 200, await stopContainer(await body(req)))
    if (req.method === 'POST' && url.pathname === '/podman/restart') return send(res, 200, await restartContainer(await body(req)))
    if (req.method === 'GET' && url.pathname === '/podman/logs') return send(res, 200, await logs(url.searchParams.get('name') || 'xavi-mcagent-01'))
    if (req.method === 'POST' && url.pathname === '/citizens/spawn') return send(res, 200, await citizensSpawn(await body(req)))
    if (req.method === 'POST' && url.pathname === '/bluemap/install-filtered-entities') return send(res, 200, await installBlueMapFilteredEntities(await body(req)))
    if (req.method === 'POST' && url.pathname === '/minecraft/restart') return send(res, 200, await restartMinecraft(await body(req)))
    return send(res, 404, { ok: false, error: 'not found' })
  } catch (err) {
    return send(res, 500, { ok: false, error: err instanceof Error ? err.message : String(err) })
  }
}).listen(PORT, '127.0.0.1', () => console.log(`[botops] listening on 127.0.0.1:${PORT}`))

function authorized(req: IncomingMessage): boolean {
  if (!TOKEN) return true
  return req.headers.authorization === `Bearer ${TOKEN}`
}

async function body(req: IncomingMessage): Promise<Json> {
  const chunks: Buffer[] = []
  for await (const chunk of req) chunks.push(Buffer.from(chunk))
  const text = Buffer.concat(chunks).toString('utf8')
  return text ? JSON.parse(text) : {}
}

function send(res: ServerResponse, code: number, data: unknown) {
  res.writeHead(code, { 'content-type': 'application/json' })
  res.end(JSON.stringify(data, null, 2))
}

async function status() {
  const ps = await run(['podman', 'ps', '-a', '--format', 'json'])
  const ports = await run(['bash', '-lc', "ss -ltnp | grep -E ':(3000|3001|3002|3003|8790|8791)\\b' || true"])
  const configPath = path.join(GENERATED, 'accounts.multi.json')
  let config: unknown = null
  if (existsSync(configPath)) config = redactConfig(JSON.parse(await readFile(configPath, 'utf8')))
  return { ok: true, podman: ps, ports, config }
}

function redactConfig(config: any) {
  return {
    ...config,
    accounts: Array.isArray(config?.accounts) ? config.accounts.map((a: any) => ({
      id: a.id, role: a.role, enabled: a.enabled, auth: a.auth,
      username: String(a.username || '').replace(/^(.).+(@.*)?$/, '$1***$2')
    })) : []
  }
}

async function writeAccounts(input: Json) {
  await mkdir(GENERATED, { recursive: true })
  const host = String(input.host || 'gpdoes.org')
  const port = Number(input.port || 25565)
  const accounts = Array.isArray(input.accounts) ? input.accounts : []
  const config = {
    server: { host, port, profilesFolder: '/auth-cache' },
    runtime: { baseUrl: 'http://127.0.0.1:8080', userId: `minecraft-server:${host}`, threadId: 'world:survival', planningIntervalMs: 7000 },
    safety: { dryRun: input.dryRun !== false, chatPrefix: '!ai', allowedControllers: ['theblobinc'] },
    accounts: accounts.map((a: any, idx: number) => ({
      id: String(a.id || `mc-bot-${String(idx + 1).padStart(2, '0')}`),
      username: String(a.username || ''), auth: 'microsoft', role: String(a.role || 'helper'), enabled: a.enabled !== false
    })).filter((a: any) => a.username)
  }
  await writeFile(path.join(GENERATED, 'accounts.multi.json'), JSON.stringify(config, null, 2) + '\n')
  await mkdir(AUTH_CACHE, { recursive: true })
  return { ok: true, path: path.join(GENERATED, 'accounts.multi.json'), config: redactConfig(config) }
}

async function startContainer(input: Json) {
  const name = String(input.name || 'xavi-mcagent-01')
  const viewerPort = Number(input.viewerPort || 3000)
  const configFile = String(input.configFile || path.join(GENERATED, 'accounts.multi.json'))
  return run(['bash', '-lc', `MCAGENT_CONTAINER_NAME=${sh(name)} MCAGENT_ACCOUNTS_FILE=${sh(configFile)} MCAGENT_ENV_FILE=${sh(PODMAN_ENV)} MCAGENT_AUTH_CACHE_DIR=${sh(AUTH_CACHE)} MCAGENT_VIEWER_PORT=${viewerPort} npm run podman:run`], 2000)
}

async function stopContainer(input: Json) {
  const name = String(input.name || 'xavi-mcagent-01')
  return run(['podman', 'rm', '-f', name])
}

async function restartContainer(input: Json) {
  await stopContainer(input).catch(() => null)
  return startContainer(input)
}

async function logs(name: string) {
  return run(['podman', 'logs', '--tail', '200', name])
}

async function citizensSpawn(input: Json) {
  const bridge = String(input.bridge || 'http://127.0.0.1:8790')
  const id = String(input.id || `xavi-npc-${Date.now()}`)
  const name = String(input.name || id)
  const role = String(input.role || 'helper')
  const location = input.location || { world: 'world', x: 59, y: 16, z: 35, yaw: 0, pitch: 0 }
  const res = await fetch(`${bridge}/npcs/spawn`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ id, name, role, location }) })
  const text = await res.text()
  return { ok: res.ok, status: res.status, body: text }
}

async function installBlueMapFilteredEntities(input: Json) {
  const pluginDir = String(input.pluginDir || '')
  if (!pluginDir || !pluginDir.endsWith('/plugins')) throw new Error('pluginDir ending in /plugins is required')
  const repo = 'TechnicJelle/BlueMapFilteredEntities'
  const api = `https://api.github.com/repos/${repo}/releases/latest`
  const meta = await fetch(api, { headers: { accept: 'application/vnd.github+json', 'user-agent': 'xavi-botops' } }).then(r => r.json() as Promise<any>)
  const asset = (meta.assets || []).find((a: any) => String(a.name || '').endsWith('.jar'))
  if (!asset) throw new Error('no jar asset found on latest release')
  const out = path.join(pluginDir, asset.name)
  return run(['bash', '-lc', `curl -L ${sh(asset.browser_download_url)} -o ${sh(out)} && ls -lh ${sh(out)}`])
}

async function restartMinecraft(input: Json) {
  const service = String(input.service || '')
  if (!/^[a-zA-Z0-9_.@-]+\.service$/.test(service)) throw new Error('valid systemd service name is required')
  return run(['systemctl', 'restart', service])
}

function sh(value: string) { return `'${String(value).replaceAll("'", "'\\''")}'` }

function run(argv: string[], timeoutMs = 30000): Promise<{ ok: boolean; code: number | null; stdout: string; stderr: string; argv: string[] }> {
  return new Promise((resolve) => {
    const child = spawn(argv[0], argv.slice(1), { cwd: ROOT, env: process.env })
    let stdout = '', stderr = ''
    const timer = setTimeout(() => child.kill('SIGTERM'), timeoutMs)
    child.stdout.on('data', d => stdout += d)
    child.stderr.on('data', d => stderr += d)
    child.on('close', code => { clearTimeout(timer); resolve({ ok: code === 0, code, stdout: stdout.slice(-12000), stderr: stderr.slice(-12000), argv }) })
  })
}
