<?php

namespace Application\Controller\SinglePage;

use Concrete\Controller\SinglePage\Login as CoreLogin;

defined('C5_EXECUTE') or die('Access Denied.');

class Login extends CoreLogin
{
    private function normalizeChatRedirect($url)
    {
        if (!is_string($url) || $url === '') {
            return $url;
        }

        $decoded = rawurldecode($url);
        $path = parse_url($decoded, PHP_URL_PATH);
        if (!is_string($path) || $path === '') {
            $path = $decoded;
        }
        $path = '/' . ltrim($path, '/');

        if ($path === '/rnn_chat' || $path === '/rnn-chat' || strpos($path, '/rnn_chat/') === 0 || strpos($path, '/rnn-chat/') === 0) {
            return '/chat/app/';
        }

        if ($path === '/chat' || $path === '/chat/' || strpos($path, '/chat/c/') === 0) {
            return '/chat/app/';
        }

        return $url;
    }

    public function getRedirectUrl()
    {
        return $this->normalizeChatRedirect(parent::getRedirectUrl());
    }

    public function getRedirectUrlFromSession()
    {
        return $this->normalizeChatRedirect(parent::getRedirectUrlFromSession());
    }

    public function login_complete()
    {
        $session = $this->app->make('session');
        foreach (['rUri', 'ccmReturnUrl', 'returnUrl', 'redirect_url'] as $key) {
            $value = $session->get($key);
            $fixed = $this->normalizeChatRedirect($value);
            if ($fixed !== $value) {
                $session->set($key, $fixed);
            }
        }

        return parent::login_complete();
    }
}
