<?php

declare(strict_types=1);

namespace Concrete\Package\Xaviviewer\Controller\SinglePage;

use Concrete\Core\Page\Controller\PageController;
use Concrete\Core\User\User;
use Symfony\Component\HttpFoundation\JsonResponse;

class Xaviviewer extends PageController
{
    private string $botOpsBase = 'http://127.0.0.1:8791';

    public function view(): void
    {
        $viewerPorts = getenv('XAVI_VIEWER_PUBLIC_PORTS') ?: getenv('MCAGENT_VIEWER_PORTS') ?: getenv('MCAGENT_VIEWER_PORT') ?: '3000';
        $screens = [];
        foreach (array_filter(array_map('trim', explode(',', $viewerPorts))) as $index => $port) {
            $screenNumber = $index + 1;
            $screens[] = [
                'label' => 'Bot Screen ' . $screenNumber,
                'port' => $port,
                'url' => '/xaviviewer/viewer/' . $screenNumber . '/',
            ];
        }

        $this->set('viewerScreens', $screens);
        $this->set('viewerPorts', $viewerPorts);
        $this->set('serverHost', getenv('XAVI_MC_SERVER_HOST') ?: 'gpdoes.org');
        $this->set('serverPort', getenv('XAVI_MC_SERVER_PORT') ?: '25565');
        $this->set('citizensBridgeUrl', getenv('XAVI_CITIZENS_BRIDGE_URL') ?: 'http://127.0.0.1:8790');
        $this->set('botOpsBase', $this->botOpsBase);
    }

    public function action_api_status(): JsonResponse
    {
        return $this->proxy('GET', '/status');
    }

    public function action_api_build(): JsonResponse
    {
        return $this->proxy('POST', '/podman/build');
    }

    public function action_api_start(): JsonResponse
    {
        return $this->proxy('POST', '/podman/start', $this->jsonInput());
    }

    public function action_api_stop(): JsonResponse
    {
        return $this->proxy('POST', '/podman/stop', $this->jsonInput());
    }

    public function action_api_logs(): JsonResponse
    {
        $name = preg_replace('/[^a-zA-Z0-9_.-]/', '', (string) $this->request->query->get('name', 'xavi-mcagent-01'));
        return $this->proxy('GET', '/podman/logs?name=' . rawurlencode($name));
    }

    public function action_api_accounts(): JsonResponse
    {
        return $this->proxy('POST', '/config/accounts', $this->jsonInput());
    }

    private function proxy(string $method, string $path, ?array $payload = null): JsonResponse
    {
        $user = new User();
        if (!$user->isSuperUser()) {
            return new JsonResponse(['ok' => false, 'error' => 'super user required'], 403);
        }

        $context = [
            'http' => [
                'method' => $method,
                'header' => "Accept: application/json\r\nContent-Type: application/json\r\n",
                'timeout' => 30,
            ]
        ];
        if ($payload !== null) {
            $context['http']['content'] = json_encode($payload);
        }

        $response = @file_get_contents($this->botOpsBase . $path, false, stream_context_create($context));
        if ($response === false) {
            return new JsonResponse(['ok' => false, 'error' => 'bot ops service unavailable', 'botOpsBase' => $this->botOpsBase], 502);
        }
        $decoded = json_decode($response, true);
        return new JsonResponse($decoded ?? ['ok' => false, 'raw' => $response]);
    }

    private function jsonInput(): array
    {
        $raw = (string) $this->request->getContent();
        $decoded = json_decode($raw, true);
        return is_array($decoded) ? $decoded : [];
    }
}
