'use strict';

(function () {
  if (customElements.get('wgrnn-manager-dashboard')) return;

  class WgrnnManagerDashboard extends HTMLElement {
    constructor() {
      super();
      this.attachShadow({ mode: 'open' });
      this._runtimeApi = '/rnn_chat/runtime_api';
      this._managerApi = '/rnn_chat/manager_api';
      this._summary = null;
      this._models = null;
      this._contract = null;
      this._error = '';
      this._loading = false;
    }

    connectedCallback() {
      this._runtimeApi = this.getAttribute('runtime-api') || window.rnnChatRuntimeApiUrl || window.runtimeApiUrl || '/rnn_chat/runtime_api';
      this._managerApi = this.getAttribute('manager-api') || window.rnnChatManagerApiUrl || window.managerApiUrl || '/rnn_chat/manager_api';
      this.render();
      this.refresh();
    }

    async refresh() {
      if (this._loading) return;
      this._loading = true;
      this._error = '';
      this.render();
      try {
        const [summary, models, contract, tables] = await Promise.all([
          this._get(`${this._runtimeApi}?action=summary`),
          this._get(`${this._runtimeApi}?action=models`),
          this._get(`${this._runtimeApi}?action=contract`),
          this._get(`${this._managerApi}?action=tables`),
        ]);
        this._summary = summary;
        this._models = models;
        this._contract = contract?.contract || contract;
        this._tables = tables;
      } catch (err) {
        this._error = err && err.message ? err.message : String(err || 'unknown error');
      } finally {
        this._loading = false;
        this.render();
      }
    }

    async _get(url) {
      const resp = await fetch(url, { credentials: 'same-origin', headers: { Accept: 'application/json' } });
      const text = await resp.text();
      let data = null;
      try { data = text ? JSON.parse(text) : {}; } catch (_) { data = { ok: false, raw: text }; }
      if (!resp.ok) {
        throw new Error(`${resp.status} from ${url}: ${data?.error || data?.detail || text.slice(0, 160)}`);
      }
      return data;
    }

    get _dbTables() {
      const contractTables = this._contract?.database?.tables;
      if (Array.isArray(contractTables) && contractTables.length) return contractTables;
      const runtimeTables = this._tables?.databases?.runtime;
      if (Array.isArray(runtimeTables) && runtimeTables.length) return runtimeTables;
      return [];
    }

    get _enabledModels() {
      const models = Array.isArray(this._models?.models) ? this._models.models : [];
      return models.filter((m) => m && m.enabled !== false);
    }

    get _capabilityCounts() {
      const counts = {};
      for (const model of this._enabledModels) {
        for (const cap of Array.isArray(model.capabilities) ? model.capabilities : []) {
          counts[cap] = (counts[cap] || 0) + 1;
        }
      }
      return Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 10);
    }

    _esc(value) {
      return String(value ?? '').replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
    }

    _json(value) {
      try { return this._esc(JSON.stringify(value, null, 2)); } catch (_) { return ''; }
    }

