      return `<span class="pill ${cls}">${this._esc(text)}</span>`;
    }

    _metric(label, value, hint = '') {
      return `<div class="metric"><div class="metric-label">${this._esc(label)}</div><div class="metric-value">${this._esc(value)}</div>${hint ? `<div class="metric-hint">${this._esc(hint)}</div>` : ''}</div>`;
