'use strict';

(function () {
  if (customElements.get('wgrnn-manager-data-workspace')) return;

  const TABLE_NOTES = {
    model_registry: 'Registered provider/model aliases exposed to WG-RNN runtime.',
    runtime_runs: 'One row per runtime inference/run bundle.',
    wgrnn_memory_updates: 'WG-RNN memory write/promote/noop events.',
    nla_activation_witnesses: 'Neural lattice activation witnesses attached to runs.',
    memory_cells: 'Current trusted/candidate memory cell state by loop/node/slot.',
    audit_events: 'Runtime audit trail and operator-visible lifecycle events.',
    corpus_documents: 'Indexed corpus documents available to runtime grounding.',
    corpus_versions: 'Corpus version manifests and activation state.',
    evidence_claims: 'Structured claims produced or consumed by evidence layer.',
    evidence_witnesses: 'Evidence witness records linked to runs and observers.',
    module_invocations: 'Tool/module invocation ledger with input/output digests.',
  };

  const TABLE_GROUPS = [
    { key: 'runtime', title: 'Runtime', tables: ['runtime_runs', 'model_registry', 'audit_events', 'module_invocations'] },
    { key: 'memory', title: 'WG-RNN Memory', tables: ['memory_cells', 'wgrnn_memory_updates', 'nla_activation_witnesses'] },
    { key: 'corpus', title: 'Corpus', tables: ['corpus_documents', 'corpus_versions'] },
    { key: 'evidence', title: 'Evidence', tables: ['evidence_claims', 'evidence_witnesses'] },
  ];

  class WgrnnManagerDataWorkspace extends HTMLElement {
    constructor() {
      super();
      this.attachShadow({ mode: 'open' });
      this._managerApi = '/rnn_chat/manager_api';
      this._runtimeApi = '/rnn_chat/runtime_api';
      this._tablesPayload = null;
      this._contract = null;
      this._selected = 'runtime_runs';
      this._error = '';
      this._loading = false;
    }

    connectedCallback() {
      this._managerApi = this.getAttribute('manager-api') || window.rnnChatManagerApiUrl || window.managerApiUrl || '/rnn_chat/manager_api';
      this._runtimeApi = this.getAttribute('runtime-api') || window.rnnChatRuntimeApiUrl || window.runtimeApiUrl || '/rnn_chat/runtime_api';
      this.render();
      this.refresh();
    }

    async refresh() {
      if (this._loading) return;
      this._loading = true;
      this._error = '';
      this.render();
      try {
        const [tables, contract] = await Promise.all([
          this._get(`${this._managerApi}?action=tables`),
          this._get(`${this._runtimeApi}?action=contract`),
        ]);
        this._tablesPayload = tables;
        this._contract = contract?.contract || contract;
        const all = this._tables;
        if (!all.includes(this._selected) && all.length) this._selected = all[0];
      } catch (err) {
        this._error = err && err.message ? err.message : String(err || 'unknown error');
      } finally {
        this._loading = false;
        this.render();
      }
    }

    async _get(url) {
      const resp = await fetch(url, { credentials: 'same-origin', headers: { Accept: 'application/json' } });
      const text = await resp.text();
      let data;
      try { data = text ? JSON.parse(text) : {}; } catch (_) { data = { ok: false, raw: text }; }
      if (!resp.ok) throw new Error(`${resp.status} from ${url}: ${data?.error || data?.detail || text.slice(0, 160)}`);
      return data;
    }

    get _tables() {
      const contractTables = this._contract?.database?.tables;
      if (Array.isArray(contractTables) && contractTables.length) return contractTables;
      const runtimeTables = this._tablesPayload?.databases?.runtime;
      if (Array.isArray(runtimeTables) && runtimeTables.length) return runtimeTables;
      return [];
    }

    _esc(value) {
      return String(value ?? '').replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
    }

    _tableButton(table) {
      const active = table === this._selected ? 'active' : '';
      return `<button class="table-btn ${active}" data-table="${this._esc(table)}"><strong>${this._esc(table)}</strong><span>${this._esc(TABLE_NOTES[table] || 'Runtime table')}</span></button>`;
    }

    _groupMarkup(group) {
      const available = group.tables.filter((t) => this._tables.includes(t));
      if (!available.length) return '';
      return `<section class="group"><h3>${this._esc(group.title)}</h3><div class="table-list">${available.map((t) => this._tableButton(t)).join('')}</div></section>`;
    }

    render() {
      const tables = this._tables;
      const selected = this._selected;
      const note = TABLE_NOTES[selected] || 'Runtime table';
      const missingGroups = tables.filter((t) => !TABLE_GROUPS.some((g) => g.tables.includes(t)));
      const contract = this._contract || window.rnnChatRuntimeContract || {};
      const sqlite = contract?.database?.sqlite === false ? 'disabled' : 'unknown';

      this.shadowRoot.innerHTML = /* html */`
        <style>
          :host { display:block; height:100%; min-height:0; background:#071018; color:#d7e6f3; font:13px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif; }
          * { box-sizing:border-box; }
          .wrap { height:100%; display:grid; grid-template-columns:340px minmax(0,1fr); overflow:hidden; }
          aside { border-right:1px solid rgba(145,184,220,.16); background:rgba(5,12,19,.82); overflow:auto; padding:14px; }
          main { overflow:auto; padding:16px; }
          .top { display:flex; justify-content:space-between; gap:12px; align-items:flex-start; margin-bottom:14px; }
          h2, h3 { margin:0; }
          h2 { font-size:1.02rem; }
          h3 { font-size:.78rem; color:#9fb8cb; text-transform:uppercase; letter-spacing:.08em; margin:16px 0 8px; }
          .sub { color:#8ba6b9; font-size:.82rem; margin-top:4px; }
          .pill { display:inline-flex; border:1px solid rgba(145,184,220,.22); background:rgba(78,137,190,.12); color:#bcd8ef; border-radius:999px; padding:4px 8px; font-size:.73rem; white-space:nowrap; }
          .pill.warn { border-color:rgba(230,184,92,.35); background:rgba(230,184,92,.10); color:#ffe4a8; }
          .actions { display:flex; gap:8px; flex-wrap:wrap; justify-content:flex-end; }
          button { font:inherit; color:inherit; cursor:pointer; }
          .refresh { border:1px solid rgba(145,184,220,.28); background:rgba(96,151,202,.16); color:#d9ecff; border-radius:10px; padding:7px 10px; }
          .table-list { display:grid; gap:7px; }
          .table-btn { width:100%; text-align:left; border:1px solid rgba(255,255,255,.08); border-radius:12px; background:rgba(255,255,255,.035); padding:9px 10px; display:grid; gap:3px; }
          .table-btn:hover { background:rgba(96,151,202,.11); }
          .table-btn.active { border-color:rgba(76,195,255,.42); background:rgba(76,195,255,.13); }
          .table-btn strong { font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:.8rem; color:#eaf6ff; }
          .table-btn span { color:#7f98ac; font-size:.76rem; }
          .card { border:1px solid rgba(114,160,200,.18); background:linear-gradient(180deg,rgba(13,29,43,.96),rgba(8,18,28,.98)); box-shadow:0 10px 30px rgba(0,0,0,.25); border-radius:14px; padding:14px; margin-bottom:14px; }
          .selected-name { font:700 1.25rem/1.2 ui-monospace,SFMono-Regular,Menlo,monospace; color:#f5fbff; }
          .grid { display:grid; grid-template-columns:repeat(3,minmax(140px,1fr)); gap:10px; }
          .metric { border:1px solid rgba(255,255,255,.08); background:rgba(0,0,0,.18); border-radius:12px; padding:10px; min-height:78px; }
          .metric-label { color:#8da8bd; font-size:.73rem; text-transform:uppercase; letter-spacing:.08em; }
          .metric-value { color:#f4fbff; font-size:1rem; margin-top:5px; font-weight:700; }
          .empty { border:1px dashed rgba(145,184,220,.22); border-radius:12px; padding:14px; color:#a8bfd1; background:rgba(0,0,0,.12); }
          .error { border-color:rgba(255,110,110,.32); background:rgba(90,20,20,.22); color:#ffc9c9; }
          code { color:#d7e6f3; }
          @media (max-width:900px) { .wrap { grid-template-columns:1fr; } aside { max-height:42vh; border-right:0; border-bottom:1px solid rgba(145,184,220,.16); } .grid { grid-template-columns:1fr; } }
        </style>
        <div class="wrap">
          <aside>
            <div class="top">
              <div>
                <h2>WG-RNN Data</h2>
                <div class="sub">Postgres runtime schema catalog. No SQLite paths.</div>
              </div>
            </div>
            ${this._error ? `<div class="card error">${this._esc(this._error)}</div>` : ''}
            ${TABLE_GROUPS.map((g) => this._groupMarkup(g)).join('')}
            ${missingGroups.length ? `<section class="group"><h3>Other</h3><div class="table-list">${missingGroups.map((t) => this._tableButton(t)).join('')}</div></section>` : ''}
            ${!tables.length ? '<div class="empty">No runtime table contract has loaded yet.</div>' : ''}
          </aside>
          <main>
            <div class="top">
              <div>
                <div class="selected-name">${this._esc(selected || 'No table selected')}</div>
                <div class="sub">${this._esc(note)}</div>
              </div>
              <div class="actions">
                <span class="pill">backend=postgres</span>
                <span class="pill">sqlite=${this._esc(sqlite)}</span>
                <span class="pill ${this._loading ? 'warn' : ''}">${this._loading ? 'refreshing' : 'ready'}</span>
                <button class="refresh" id="refreshBtn">Refresh</button>
              </div>
            </div>
            <section class="card">
              <h3>Migration Status</h3>
              <div class="grid">
                <div class="metric"><div class="metric-label">Catalog tables</div><div class="metric-value">${tables.length}</div></div>
                <div class="metric"><div class="metric-label">Primary store</div><div class="metric-value">Postgres</div></div>
                <div class="metric"><div class="metric-label">Vector store</div><div class="metric-value">${this._esc(contract?.database?.vector || 'milvus_optional')}</div></div>
              </div>
            </section>
            <section class="card">
              <h3>Row Browser Boundary</h3>
