                <code>${this._esc(selected || 'runtime_runs')}</code> without adding direct DB credentials to Concrete PHP.
              </div>
            </section>
          </main>
        </div>
      `;

      this.shadowRoot.querySelectorAll('[data-table]').forEach((btn) => {
        btn.addEventListener('click', () => {
